package com.honorablemobile

import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.Config

import android.app.AlertDialog
import android.net.Uri
import app.honorable.editor.EditorAccessMode
import org.junit.Assert.*
import org.junit.Test

/** Real visible-approval/project mutation gates, with metadata-only dialog membership. */
@RunWith(RobolectricTestRunner::class)
@Config(sdk = [34], manifest = Config.NONE, application = android.app.Application::class)
class VideoSlipWindowReviewTest {
 private val unsafe=JvmTestAllocator
 private fun set(a:Any,n:String,v:Any?)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.set(a,v)
 private fun get(a:Any,n:String)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.get(a)
 private fun call(a:Any,n:String,vararg args:Any?)=a.javaClass.declaredMethods.single{it.name==n&&it.parameterCount==args.size}.apply{isAccessible=true}.invoke(a,*args)
 private fun activity()=(unsafe.allocateInstance(HonorableVideoEditorActivity::class.java)as HonorableVideoEditorActivity).also{val p=VideoEditProject(5000);p.restore(listOf(VideoSegment(0,5000,captions=listOf(VideoCaption(0,500,"A"),VideoCaption(1000,1500,"B")),captionSourceUri="content://synthetic/subtitles")),soundtrack=VideoSoundtrack("content://synthetic/music",10000,loop=false));set(it,"project",p);set(it,"source",Uri.parse("content://synthetic/video"));set(it,"primaryDurationMs",5000L);set(it,"accessMode",EditorAccessMode.GUEST_BASIC);set(it,"workspaceActive",true);set(it,"importedSources",linkedMapOf<String,VideoSource>())}
 private fun showing(d:AlertDialog,value:Boolean){android.app.Dialog::class.java.getDeclaredField("mDecor").apply{isAccessible=true}.set(d,if(value)unsafe.allocateInstance(android.view.View::class.java)else null)}
 private fun dialog()=(unsafe.allocateInstance(AlertDialog::class.java)as AlertDialog).also{showing(it,true)}
 private fun capture(a:HonorableVideoEditorActivity)=call(a,"captureCaptionReview")as VideoCaptionReviewState
 private fun slipActivity():HonorableVideoEditorActivity=activity().also{a->val p=VideoEditProject(20000);p.restore(listOf(VideoSegment(1000,5000,speed=2f,title="Moving",captions=listOf(VideoCaption(3500,4500,"Current cue"),VideoCaption(6000,6500,"Later cue")),captionSourceUri="content://synthetic/subtitles",motion=VideoMotion(true,endZoom=1.4f,anchorStartMs=1000,anchorEndMs=5000)),VideoSegment(8000,12000,title="Neighbor")),soundtrack=VideoSoundtrack("content://synthetic/music",10000,loop=false));set(a,"project",p);set(a,"primaryDurationMs",20000L);set(a,"durationMs",20000)}
 private fun pair(a:HonorableVideoEditorActivity):Pair<AlertDialog,AlertDialog>{val editor=dialog();val confirmation=dialog();set(a,"slipWindowEditor",editor);set(a,"slipWindowConfirmation",confirmation);set(a,"captionReviewDialogs",linkedSetOf(editor,confirmation));return editor to confirmation}
 private fun commit(a:HonorableVideoEditorActivity,pair:Pair<AlertDialog,AlertDialog>,r:VideoCaptionReviewState,start:Long=3000)=call(a,"commitSlipWindowReview",pair.first,pair.second,r,get(a,"project"),0,start)as Boolean
 @Test fun exactVisibleSlipKeepsLengthNeighborSettingsAnchorsAndOneUndo(){val a=slipActivity();val p=get(a,"project")as VideoEditProject;val old=p.segments;val music=p.soundtrack;val total=VideoPlaybackTime.durationUs(old);val duration=old[0].durationUs;assertEquals(1,VideoCaptions.resolve(old).size);val pair=pair(a);val r=capture(a);assertTrue(commit(a,pair,r));assertEquals(old[0].copy(startMs=3000,endMs=7000),p.segments[0]);assertEquals(duration,p.segments[0].durationUs);assertEquals(total,VideoPlaybackTime.durationUs(p.segments));assertSame(old[1],p.segments[1]);assertSame(music,p.soundtrack);assertEquals(2,VideoCaptions.resolve(p.segments).size);assertNull(get(a,"slipWindowConfirmation"));assertTrue(p.undo());assertEquals(old,p.segments);assertFalse(p.canUndo);assertTrue(p.redo());assertEquals(3000L,p.segments[0].startMs)}
 @Test fun eitherUntrackedDismissedOrReplacedDialogRejects(){for(which in listOf(0,1))for(flag in listOf("untracked","dismissed","replaced")){val a=slipActivity();val p=get(a,"project")as VideoEditProject;val old=p.segments;val pair=pair(a);val r=capture(a);when(flag){"untracked"->set(a,"captionReviewDialogs",linkedSetOf(if(which==0)pair.second else pair.first));"dismissed"->showing(if(which==0)pair.first else pair.second,false);else->set(a,if(which==0)"slipWindowEditor"else"slipWindowConfirmation",dialog())};assertFalse("$which/$flag",commit(a,pair,r));assertSame(old,p.segments);assertFalse(p.canUndo)}}
 @Test fun staleForegroundGenerationSourceDurationRangeMusicSessionAndRecoveryReject(){for(flag in listOf("pause","generation","source","duration","range","music","mode","recovery","busy")){val a=slipActivity();val p=get(a,"project")as VideoEditProject;val old=p.segments;val pair=pair(a);val r=capture(a);when(flag){"pause"->set(a,"workspaceActive",false);"generation"->set(a,"captionReviewGeneration",r.generation+1);"source"->set(a,"source",Uri.parse("content://synthetic/other"));"duration"->set(a,"primaryDurationMs",20001L);"range"->set(a,"selectedClip",1);"music"->p.setSoundtrack(p.soundtrack!!.copy(volume=.5f));"mode"->set(a,"accessMode",EditorAccessMode.ACCOUNT);"recovery"->set(a,"recoveryBytes",byteArrayOf(1));else->set(a,"saving",true)};assertFalse(flag,commit(a,pair,r));assertSame(old,p.segments);assertNull(get(a,"slipWindowConfirmation"))}}
 @Test fun consumedApprovalCannotRepeatOrReviveThroughUndo(){val a=slipActivity();val p=get(a,"project")as VideoEditProject;val pair=pair(a);val r=capture(a);assertTrue(commit(a,pair,r));assertFalse(commit(a,pair,r));assertTrue(p.undo());assertEquals(true,call(a,"canApplyCaptionReview",r));assertFalse(commit(a,pair,r));assertFalse(p.canUndo);assertTrue(p.canRedo)}
 @Test fun foreignOldPairCannotConsumeNewConfirmation(){val a=slipActivity();val old=pair(a);val current=pair(a);val r=capture(a);assertFalse(commit(a,old,r));assertSame(current.second,get(a,"slipWindowConfirmation"));assertTrue(commit(a,current,r))}
 @Test fun invalidOrIdenticalWindowConsumesOnlyOwnApprovalWithoutHistory(){for(start in listOf(-1L,1000L,17000L)){val a=slipActivity();val p=get(a,"project")as VideoEditProject;val old=p.segments;val pair=pair(a);val r=capture(a);try{commit(a,pair,r,start);fail("Accepted $start")}catch(e:java.lang.reflect.InvocationTargetException){assertTrue(e.cause is IllegalArgumentException)};assertSame(old,p.segments);assertFalse(p.canUndo);assertNull(get(a,"slipWindowConfirmation"));assertFalse(commit(a,pair,r,3000))}}
 @Test fun slippedWindowSurvivesDraftRecoveryWithAnchoredCaptionsMotionAndMusic(){val a=slipActivity();val p=get(a,"project")as VideoEditProject;val pair=pair(a);val r=capture(a);assertTrue(commit(a,pair,r));val first=p.segments[0];val draft=VideoDraft(20000,p.segments,0,first.startMs,first.startMs,first.endMs,soundtrack=p.soundtrack);val restored=requireNotNull(VideoDraftCodec.decode(VideoDraftCodec.encode(draft),20000));assertEquals(draft,restored);assertEquals("content://synthetic/subtitles",restored.segments[0].captionSourceUri);assertEquals(3500L,restored.segments[0].captions[0].startMs);assertEquals(5000L,restored.segments[0].motion.anchorEndMs);assertEquals(8000L,restored.segments[1].startMs);assertEquals(2,VideoCaptions.resolve(restored.segments).size)}
 @Test fun pausedSlipEntryStillReturnsBeforePreviewWidgets(){val a=slipActivity();set(a,"workspaceActive",false);call(a,"slipSourceWindow");assertNull(get(a,"slipWindowEditor"));assertNull(get(a,"slipWindowConfirmation"));assertFalse((get(a,"project")as VideoEditProject).canUndo)}
}
